SELECT CASE WHEN suppliers.country IN ('UK', 'DE') THEN 'priority' ELSE 'other' END AS country_group, ROUND(AVG(products.price), 2) AS avg_price, COUNT(products.cost) AS cost_count FROM products LEFT OUTER JOIN suppliers ON products.supplier_id = suppliers.id WHERE suppliers.city IN ('Singapore', 'New York', 'Bangkok') GROUP BY CASE WHEN suppliers.country IN ('UK', 'DE') THEN 'priority' ELSE 'other' END ORDER BY avg_price;
